#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {}
    void meow() const {
        cout << name << "：喵～" << endl;
    }
};

class Kitten : ____ Cat {
public:
    Kitten(string n) : ____(n) {}
    void wag() const {
        cout << name << " 摇起了尾巴" << endl;
    }
