#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
    int fish;
public:
    Cat(string n, int f) : name(n), fish(f) {
        cout << "猫妈妈：" << name << endl;
    }
    ~Cat() {
        cout << "猫妈妈走了" << endl;
    }
};

class Kitten : public Cat {
public:
    Kitten(string n, int f) : Cat(n, f) {
        cout << "小猫：" << name << " " << fish << " 条" << endl;
    }
    ~Kitten() {
        cout << "小猫走了" << endl;
    }
};

int main() {
    Kitten k("小橘", 3);
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Cat {
    string name;
protected:
    int fish;
public:
    Cat(string n, int f) : name(n), fish(f) {}
    void showName() const {
        cout << "本喵是" << name << "喵" << endl;
    }
};

class Kitten : public Cat {
public:
    Kitten(string n, int f) : Cat(n, f) {}
    void eat() {
        fish = fish + 1;
        cout << "吃了一条，现在 " << fish << " 条" << endl;
    }
};

int main() {
    Kitten k("小橘", 3);
    k.showName();
    k.eat();
    k.eat();
    return 0;
}
